package ru.yamap.cache

class MapCacheItem {
    @JvmField
    var id: Number? = null
    @JvmField
    var name: String? = null
    @JvmField
    var size: Number? = null
    @JvmField
    var releaseTime: Number? = null
    @JvmField
    var parentId: Number? = null
    @JvmField
    var description: String? = null
}
